for p,d in zip(source['problems'][:10],D):
 pid=p['id'];under,rec,start,verify,pit,retry=d
 sections=[]
 def section(kind,title,body,cls='formal'):
  return f'<div class="layer {cls}" data-explanation="{kind}"><h4>{title}</h4>{body}</div>'
 para=lambda x:'<p>'+x+'</p>'
 sections.append(section('understand','문제에서 무엇을 묻는지 읽어요',para(under),'eli5'))
 sections.append(section('recall','이 문제를 봤을 때 떠올릴 개념과 공식',''.join(map(para,rec))))
 sections.append(section('start','종이에 적는 실제 첫 줄',para(start)))
 diag=[x for x in p['reference_steps'] if re.match(r'^\(\d+\)',x)]
 answer=p['reference_answer'].split(': ',1)[1]
 ending=f'따라서 답은 {answer}예요.'
 if pid in {'p3','p9'}:ending=f'틀려요로 판정된 보기 {answer}가 이 부정형 문제의 답이에요.'
 solve='<div data-subpart="main">'+''.join(para(x) for x in diag)+para(ending)+'</div>'
 sections.append(section('solve','왜 이렇게 푸는지 함께 따라가요',solve))
 sections.append(section('verify','완성 답과 검산','<div data-subpart="main">'+para(verify)+'</div>'))
 sections.append(section('pitfall','여기서 헷갈리기 쉬워요',para(pit),'warn'))
 sections.append(section('retry','설명을 닫고 다시 확인해요','<ul>'+''.join('<li>'+x+'</li>' for x in retry)+'</ul>'))
 sections.append('<div class="sum" hidden><div class="summary-group"><h4>떠올릴 개념·공식</h4>'+para(rec[0].split('。')[0])+'</div><div class="summary-group"><h4>첫 줄</h4>'+para(start)+'</div><div class="summary-group"><h4>답과 검산</h4>'+para('답 '+answer+'. '+verify.split('。')[0])+'</div></div>')
 text='\n'.join(sections)+'\n';(r/'explanations'/f'{pid}.html').write_text(text)
 assert text.count('data-explanation=')==7 and text.count('data-subpart="main"')==2
 print(pid,answer)
